{
  // THE SECRET-ROOM DOOR: a gold arch next to a Dot's secret. Stand on it and press Down and you are on the other side (args: destination tile x, y, back (1 = the way home), door height in px).
  DD.defineEntity('w10door', {
    spawn: t => { const a = t.args || [0, 0, 0, 24], h = a[3] || 24; return { x: t.x + 1, y: t.y + 16 - h, w: 14, h, t: 0, to: a }; },
    stomp: () => false,
    update(e, G) {
      e.t++; if (G.s && G.s.doorCd > 0) G.s.doorCd--;
      const s = G.s || (G.s = {}); if (s.doorCd > 0) return;
      const p = G.pl, to = e.to;
      if (!DD.door(e)) return;   // press Down on the door to go through
      s.doorCd = 90;
      DD.stars(DD.cx(e), e.y + 8, 8, to[2] ? '#9fd8ff' : '#ffe680'); DD.SFX.wind && DD.SFX.wind();
      p.x = to[0] * 16 + 1; p.y = (to[1] + 1) * 16 - p.h; p.vx = 0; p.vy = 0; p.rolling = false;
      G.safe = { x: p.x, y: p.y };
      if (!to[2]) { s.roomBack = G.cpSafe; G.cpSafe = { x: p.x, y: p.y }; } else if (s.roomBack) G.cpSafe = s.roomBack;   // a fall in the room puts you back in the room; leaving restores the real checkpoint
      G.cam.x = Math.max(0, DD.cx(p) - DD.VW / 2); G.cam.y = Math.max(0, DD.bot(p) - DD.VH * 0.62);
    },
    draw(e, ctx) {
      const X = DD.wx(e.x), Y = DD.wy(e.y), k = 0.5 + 0.5 * Math.sin(e.t / 9), back = e.to[2], c1 = back ? '#9fd8ff' : '#f0c84a', c2 = back ? '#e6f6ff' : '#fff2a6';
      ctx.save(); ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createRadialGradient(X + 7, Y + e.h / 2, 1, X + 7, Y + e.h / 2, 26); g.addColorStop(0, back ? 'rgba(150,216,255,' + (0.3 + 0.2 * k) + ')' : 'rgba(255,214,90,' + (0.3 + 0.2 * k) + ')'); g.addColorStop(1, 'rgba(255,214,90,0)');
      ctx.fillStyle = g; ctx.fillRect(X - 20, Y - 20, 54, e.h + 40); ctx.restore();
      ctx.fillStyle = '#120a10'; ctx.fillRect(X + 1, Y + 2, 12, e.h - 2);
      ctx.fillStyle = c1; ctx.fillRect(X, Y + 2, 2, e.h - 2); ctx.fillRect(X + 12, Y + 2, 2, e.h - 2); ctx.fillRect(X + 1, Y, 12, 3); ctx.fillRect(X + 2, Y - 1, 10, 1);
      ctx.fillStyle = c2; ctx.fillRect(X, Y + 2, 1, e.h - 2); ctx.fillRect(X + 3, Y, 6, 1);
      ctx.fillStyle = Math.floor(e.t / 8) % 2 ? c2 : c1; ctx.fillRect(X + 6, Y + e.h / 2 - 2 + Math.round(k), 2, 4);
    },
  });
}

